import{_ as t,o as e,c as o,a3 as a}from"./chunks/framework.qCVWde4n.js";const b=JSON.parse('{"title":"nanoMuse 品牌规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/brand.md","filePath":"zh/brand.md"}'),c={name:"zh/brand.md"};function r(n,d,i,l,s,h){return e(),o("div",null,[...d[0]||(d[0]=[a('<h1 id="nanomuse-品牌" tabindex="-1">nanoMuse 品牌规范 <a class="header-anchor" href="#nanomuse-品牌" aria-label="Permalink to &quot;nanoMuse 品牌规范 {#nanomuse-品牌}&quot;">​</a></h1><p>本规范于 2026-09-24 确定。App 图标和界面配色采用同一套设计：界面的颜色取自图标，使 App 内外的视觉风格保持一致。</p><p>本页的设计变量（design token）是颜色等样式的统一名称，例如 <code>primary</code>。SVG 是可以无损缩放的矢量图格式，PNG 则是由像素组成的位图。</p><h2 id="the-mark" tabindex="-1">标志 <a class="header-anchor" href="#the-mark" aria-label="Permalink to &quot;标志 {#the-mark}&quot;">​</a></h2><p>标志由一条连续笔画构成，整体像字母 <strong>N</strong>。笔画从带钩的起点出发，经过一个圆弧形的峰顶、一条长斜线和一个收紧的谷底，最后向上收笔。整个图形只有一个拱形，设计上更接近连贯的书写动作，而不是规整的印刷字母。</p><ul><li>原始文件是 <code>assets/brand/nanomuse-icon-source-1024.png</code>，内容为品牌蓝背景上的白色圆角方块。这是最终渲染图，其他资源都由它派生。</li><li><code>assets/brand/nanomuse-mark.svg</code> 只包含标志笔画。笔画转换为一条带渐变填充的路径，<code>viewBox</code> 为 <code>0 0 100 100</code>，使用图标方块的坐标系。<code>viewBox</code> 定义 SVG 内部坐标的范围。</li><li><code>assets/brand/nanomuse-icon.svg</code> 将白色圆角方块（<code>rx=27</code>）与标志组合，作为 App 图标。<code>rx</code> 是圆角半径。</li><li><code>assets/brand/nanomuse-icon-on-blue.svg</code> 是带品牌蓝背景的版本，仅用于应用商店页面和启动画面。README、网站、社交分享卡片、favicon（浏览器标签页上的小图标）等代表 App 身份的地方，都使用白色方块、标志和细边框的版本，不加蓝色背景。</li><li><code>assets/brand/nanomuse-mark-rgba-688.png</code> 是宽 688 px、带透明通道的笔画位图，用于无法使用矢量图的场景。px 表示像素。</li><li><code>docs/app-icon.png</code> 是 512 px 的图标成品：圆角半径为边长的 27 %，方块外透明，并带有 <code>#D9D9DE</code> 细边框，保证放在白色背景上也能看清轮廓。README 的头图，以及将 nanoMuse 作为 App 展示的地方，都使用这张图。</li></ul><p>App 图标与聊天形象用途不同。默认聊天形象是随附的小龙，资源位于 <code>web/public/avatars/</code> 和 Android App 的 <code>avatar/</code> 中。用户也可以选择带底色的 emoji，或在形象工作室生成自己的形象。早期使用的小熊猫已于 0.1.23 移除。</p><p>不要把小龙或旧版小熊猫用作启动器图标，也不要把 N 标志用作聊天形象。</p><h2 id="colour" tabindex="-1">颜色 <a class="header-anchor" href="#colour" aria-label="Permalink to &quot;颜色 {#colour}&quot;">​</a></h2><p>以下颜色从图标中测得。</p><table tabindex="0"><thead><tr><th>设计变量</th><th>值</th><th>用途</th></tr></thead><tbody><tr><td><code>brand.stroke.start</code></td><td><code>#015CFB</code></td><td>标志渐变的起始颜色，位于左端</td></tr><tr><td><code>brand.stroke.end</code></td><td><code>#0186FB</code></td><td>标志渐变的结束颜色，位于右端</td></tr><tr><td><code>brand.blue</code></td><td><code>#0078FD</code></td><td>图标方块背后的背景色，以及启动画面和头图的背景色</td></tr><tr><td><code>tile</code></td><td><code>#FFFFFF</code></td><td>图标的白色方块</td></tr></tbody></table><h3 id="light-theme" tabindex="-1">浅色主题 <a class="header-anchor" href="#light-theme" aria-label="Permalink to &quot;浅色主题 {#light-theme}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设计变量</th><th>值</th><th>对比度</th><th>用途</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#015CFB</code></td><td>白色背景上为 5.35</td><td>链接、带白色文字的主按钮、状态行</td></tr><tr><td><code>primary.container</code></td><td><code>#E5F0FF</code></td><td>—</td><td>选中行、标签</td></tr><tr><td><code>ink</code></td><td><code>#000000</code></td><td>白色背景上为 21</td><td>用户消息气泡配白字；发送和「回到最新」圆形按钮配白色箭头；当前标签的圆形底色</td></tr><tr><td><code>pill</code></td><td><code>#F2F2F7</code></td><td></td><td>智能体的消息气泡</td></tr><tr><td><code>primary.tint</code></td><td><code>#EEF5FF</code></td><td>—</td><td>需要轻微突出显示的区域</td></tr><tr><td><code>bg</code></td><td><code>#FFFFFF</code></td><td></td><td>聊天背景、底部胶囊栏、菜单和抽屉面板</td></tr><tr><td><code>bg.grouped</code></td><td><code>#F2F2F7</code></td><td>—</td><td>设置页面，保留 OpenMinis 原有配色</td></tr><tr><td><code>surface</code></td><td><code>#FFFFFF</code></td><td>—</td><td>卡片和输入框</td></tr></tbody></table><p>对比度表示前景与背景在亮度上的差异。数值越大，通常越容易分辨；这里的数值均对应表中指定的背景色。</p><h3 id="dark-theme" tabindex="-1">深色主题 <a class="header-anchor" href="#dark-theme" aria-label="Permalink to &quot;深色主题 {#dark-theme}&quot;">​</a></h3><table tabindex="0"><thead><tr><th>设计变量</th><th>值</th><th>对比度</th><th>用途</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#58A6FF</code></td><td>在 <code>#000</code> 上为 8.3，在 <code>#1C1C1E</code> 上为 6.7</td><td>链接、带黑色文字的按钮、状态行</td></tr><tr><td><code>primary.container</code></td><td><code>#1A2B4A</code></td><td>—</td><td>选中行、标签</td></tr><tr><td><code>ink</code></td><td><code>#FFFFFF</code></td><td>在 <code>#000</code> 上为 21</td><td>用户消息气泡配黑字；发送和「回到最新」圆形按钮配黑色箭头；当前标签的圆形底色</td></tr><tr><td><code>pill</code></td><td><code>#1C1C1E</code></td><td></td><td>智能体的消息气泡</td></tr><tr><td><code>bg</code> / <code>surface</code> / <code>surface.2</code></td><td><code>#000000</code> / <code>#1C1C1E</code> / <code>#2C2C2E</code></td><td>—</td><td>保留 OpenMinis 原有配色</td></tr></tbody></table><p>界面只使用一种强调色。OpenMinis 原来分别用 iOS 蓝、橙、绿显示的代码块、思考文字和链接，统一改用 <code>primary</code> 和中性色。</p><p>对话区域以黑白灰为主。用户消息气泡、发送按钮和当前标签使用 <code>ink</code>；蓝色只用于链接和状态行。Android 的对应定义在 <code>ChatColors.kt</code> 中，由 <code>scripts/rebrand.py</code> 生成。小龙自身的颜色只用于形象，不作为界面配色。</p><h2 id="android-mapping-done-in-s1" tabindex="-1">Android 中的对应实现（S1 已完成） <a class="header-anchor" href="#android-mapping-done-in-s1" aria-label="Permalink to &quot;Android 中的对应实现（S1 已完成） {#android-mapping-done-in-s1}&quot;">​</a></h2><ul><li>自适应图标由三层组成：背景层为纯白 <code>#FFFFFF</code>；前景层为标志，使用 <code>VectorDrawable</code>，其 <code>fillColor</code> 为上述两个色标构成的线性渐变；单色层使用相同路径和纯色填充，由 Android 根据主题着色。自适应图标是可适配不同启动器裁切形状的 Android 图标。</li><li>图标外观沿用 OpenMinis 的 activity 别名机制，即用不同启动入口显示不同图标。「自动」和「浅色」使用白色方块；「深色」使用 <code>#0F1B33</code> 方块和白色标志。</li><li>通知栏小图标使用纯白标志，尺寸为 24 dp。dp 是 Android 按屏幕密度换算的界面尺寸单位。</li><li>发布时不得包含旧的 OpenMinis 图标、名称或字母 n 版图标草稿。</li></ul><h2 id="don-ts" tabindex="-1">使用限制 <a class="header-anchor" href="#don-ts" aria-label="Permalink to &quot;使用限制 {#don-ts}&quot;">​</a></h2><ul><li>标志只能使用蓝色渐变、纯白或纯黑。</li><li>不要旋转标志、添加描边或给笔画加阴影。</li><li>标志放在品牌蓝背景上时，必须保留白色方块，以保证对比度。</li><li>不要使用其他产品的标志、名称或品牌蓝作为素材，只使用 nanoMuse 自己的标志。</li></ul>',22)])])}const u=t(c,[["render",r]]);export{b as __pageData,u as default};
